function check([seq], actual, expected) {
  if (!Array.isArray(actual) || actual.length !== seq.length) return false;
  // The best possible split halves the deepest nesting of seq, rounded up.
  let depth = 0, deepest = 0;
  for (const ch of seq) {
    depth += ch === '(' ? 1 : -1;
    deepest = Math.max(deepest, depth);
  }
  const limit = Math.ceil(deepest / 2);
  const open = [0, 0];
  for (let i = 0; i < seq.length; i++) {
    const side = actual[i];
    if (side !== 0 && side !== 1) return false;
    open[side] += seq[i] === '(' ? 1 : -1;
    if (open[side] < 0 || open[side] > limit) return false;
  }
  return open[0] === 0 && open[1] === 0;
}

