function validate([seq]) {
  if (typeof seq !== 'string' || seq.length < 1 || seq.length > 10000) return 'seq needs 1 to 10000 characters.';
  if (/[^()]/.test(seq)) return "seq may contain only '(' and ')'.";
  let depth = 0;
  for (const ch of seq) {
    depth += ch === '(' ? 1 : -1;
    if (depth < 0) return 'seq must be a valid parentheses string.';
  }
  if (depth !== 0) return 'seq must be a valid parentheses string.';
  return null;
}

