function maxDepthAfterSplit(seq) {
  // Count through every labelling like a binary counter and keep the shallowest valid one.
  const n = seq.length;
  const pick = new Array(n).fill(0);
  let best = Infinity, bestPick = null;
  for (;;) {
    const open = [0, 0];
    let deepest = 0, valid = true;
    for (let i = 0; i < n && valid; i++) {
      open[pick[i]] += seq[i] === '(' ? 1 : -1;
      if (open[pick[i]] < 0) valid = false;
      deepest = Math.max(deepest, open[pick[i]]);
    }
    if (valid && open[0] === 0 && open[1] === 0 && deepest < best) { best = deepest; bestPick = pick.slice(); }
    let i = 0;
    while (i < n && pick[i] === 1) pick[i++] = 0;
    if (i === n) break;
    pick[i] = 1;
  }
  return bestPick;
}

