function generate(rand, size) {
  const randomVps = (pairs, bias) => {
    let out = '', opened = 0, closed = 0;
    while (closed < pairs) {
      if (opened < pairs && (opened === closed || rand() < bias)) { out += '('; opened++; }
      else { out += ')'; closed++; }
    }
    return out;
  };
  if (size === 'small') {
    const pairs = 1 + Math.floor(rand() * 7);
    return [randomVps(pairs, 0.3 + rand() * 0.5)];
  }
  const pairs = 3000 + Math.floor(rand() * 2001);
  const shape = Math.floor(rand() * 3);
  if (shape === 0) return [randomVps(pairs, 0.5)];
  if (shape === 1) return [randomVps(pairs, 0.85)];
  // A few deep towers side by side.
  let out = '';
  while (out.length < 2 * pairs - 1000) {
    const height = 1 + Math.floor(rand() * 500);
    out += '('.repeat(height) + ')'.repeat(height);
  }
  return [out];
}
